// MAIN CHANNEL: YouTube most-popular chart, WORLDWIDE.
// The Data API has no global chart - "worldwide" means polling every major
// region and aggregating. Downstream, a video trending in several regions is
// merged into ONE row ranked by how many regions it charts in.
// Cost: 1 quota unit per region (~28/run) out of 10.000 free units per day.
const regions = [
  // Americas
  'US', 'CA', 'BR', 'MX', 'AR', 'CO',
  // Europe
  'GB', 'DE', 'FR', 'ES', 'IT', 'NL', 'PL', 'SE', 'TR',
  // Asia-Pacific
  'IN', 'JP', 'KR', 'ID', 'PH', 'VN', 'TH', 'AU', 'NZ',
  // Middle East + Africa
  'SA', 'AE', 'EG', 'NG', 'ZA',
];

return regions.map(regionCode => ({ json: { platform: 'youtube', regionCode } }));

// Pair each API response back to the region that produced it (index-safe:
// the HTTP node emits one output item per input item, in order).
const regions = $('YouTube regions').all();

return $input.all().map((item, i) => ({
  json: {
    data: item.json.data ?? '',
    geo: regions[i]?.json?.regionCode || 'global',
  },
}));

// Secondary social sources - public platform APIs, no auth, no website scraping.
const BSKY = 'https://public.api.bsky.app/xrpc/';
const HOT = 'at://did:plc:z72i7hdynmk6r22z27h6tvur/app.bsky.feed.generator/whats-hot';

const sources = [
  // Bluesky: What's Hot posts (videos arrive as HLS playlist links)
  { platform: 'bluesky',  url: `${BSKY}app.bsky.feed.getFeed?feed=${encodeURIComponent(HOT)}&limit=50` },
  // Bluesky: trending topics -> the "categories" view
  { platform: 'bluesky',  url: `${BSKY}app.bsky.unspecced.getTrendingTopics?limit=15` },
  // Mastodon: trending posts (video/gifv attachments) + trending hashtags
  { platform: 'mastodon', url: 'https://mastodon.social/api/v1/trends/statuses?limit=40' },
  { platform: 'mastodon', url: 'https://mastodon.social/api/v1/trends/tags?limit=15' },
  // Reddit: top of the day, subreddit doubles as the category.
  // Firecrawl cannot be used here - old.reddit.com/robots.txt is "Disallow: /"
  // and Firecrawl honours robots.txt (403). This RSS feed is Reddit's own
  // syndication endpoint, but it allows only ~1 request per 60s per IP,
  // so keep this to ONE Reddit URL unless you add a Reddit OAuth credential.
  { platform: 'reddit',   url: 'https://www.reddit.com/r/all/top.rss?t=day&limit=75' },
];

return sources.map(json => ({ json }));

// ---- Normalize SOCIAL MEDIA trends (Reddit / Bluesky / Mastodon / YouTube) ----
const scraped_at = new Date().toISOString();

const YT_CATS = {'1':'Film & Animation','2':'Autos & Vehicles','10':'Music','15':'Pets & Animals','17':'Sports','19':'Travel & Events','20':'Gaming','22':'People & Blogs','23':'Comedy','24':'Entertainment','25':'News & Politics','26':'Howto & Style','27':'Education','28':'Science & Technology','29':'Nonprofits & Activism','30':'Movies','31':'Anime/Animation','42':'Shorts','44':'Trailers'};

const VIDEO_RE = /(v\.redd\.it|youtube\.com\/(watch|shorts)|youtu\.be\/|tiktok\.com\/.*video\/\d+|instagram\.com\/(reel|tv)\/|streamable\.com|redgifs\.com|twitch\.tv\/videos|\.(mp4|mov|webm|m3u8)(\?|$))/i;

const dec = (s) => String(s == null ? '' : s)
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#0?39;|&apos;/g, "'").replace(/&#0?32;/g, ' ')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
  .replace(/&amp;/g, '&').trim();

const tag = (xml, name) => {
  const m = xml.match(new RegExp('<' + name + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + name + '>'));
  return m ? dec(m[1]) : '';
};
const attr = (xml, re) => { const m = xml.match(re); return m ? dec(m[1]) : ''; };
const strip = (html) => dec(String(html || '').replace(/<br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const clip = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const hashtag = (text) => { const m = String(text).match(/(?:^|\s)#([A-Za-z0-9_]{2,30})/); return m ? m[1] : ''; };

const row = (o) => ({
  platform: '', geo: 'global', category: '', rank: 0, title: '', url: '',
  video_url: '', has_video: 'no', video_thumbnail: '', author: '',
  metric_name: '', metric_value: null, context: '', published_at: '', ...o,
});

// --- Reddit: top posts of the day, subreddit = category ---
function parseReddit(body) {
  const out = [];
  (body.match(/<entry>[\s\S]*?<\/entry>/g) || []).forEach((b, i) => {
    const title = tag(b, 'title');
    if (!title) return;
    const content = tag(b, 'content');
    const links = [...content.matchAll(/href="([^"]+)"/g)].map((m) => dec(m[1]));
    const video = links.find((u) => VIDEO_RE.test(u)) || '';
    out.push(row({
      platform: 'reddit',
      category: attr(b, /<category[^>]*label="r\/([^"]+)"/) || attr(b, /<category[^>]*term="([^"]+)"/),
      rank: i + 1,
      title,
      url: attr(b, /<link[^>]*href="([^"]+)"/),
      video_url: video,
      has_video: video ? 'yes' : 'no',
      video_thumbnail: attr(content, /<img src="([^"]+)"/),
      author: tag(b, 'name'),
      metric_name: 'top_rank_24h',
      metric_value: i + 1,
      published_at: tag(b, 'updated'),
    }));
  });
  return out;
}

// --- Bluesky: What's Hot feed (videos come through as HLS playlists) ---
function parseBlueskyFeed(data) {
  return (data.feed || []).map((f, i) => {
    const p = f.post || {};
    const rec = p.record || {};
    const e = p.embed || {};
    const vid = e.$type === 'app.bsky.embed.video#view' ? e
      : (e.media && e.media.$type === 'app.bsky.embed.video#view' ? e.media : null);
    const ext = e.external || (e.media && e.media.external) || {};
    const extVideo = VIDEO_RE.test(ext.uri || '') ? ext.uri : '';
    const handle = p.author?.handle || '';
    const rkey = String(p.uri || '').split('/').pop();
    const text = strip(rec.text);
    return row({
      platform: 'bluesky',
      category: hashtag(rec.text) || 'whats_hot',
      rank: i + 1,
      title: clip(text || ext.title || '(media post)', 300),
      url: handle && rkey ? `https://bsky.app/profile/${handle}/post/${rkey}` : (p.uri || ''),
      video_url: vid?.playlist || extVideo,
      has_video: vid?.playlist || extVideo ? 'yes' : 'no',
      video_thumbnail: vid?.thumbnail || ext.thumb || '',
      author: handle,
      metric_name: 'likes',
      metric_value: p.likeCount ?? null,
      context: `reposts=${p.repostCount ?? 0}; replies=${p.replyCount ?? 0}`,
      published_at: rec.createdAt || p.indexedAt || '',
    });
  });
}

// --- Bluesky: trending topics (the "categories" view) ---
function parseBlueskyTopics(data) {
  return (data.topics || []).map((t, i) => row({
    platform: 'bluesky',
    category: 'trending_topic',
    rank: i + 1,
    title: t.topic || '',
    url: t.link ? 'https://bsky.app' + t.link : '',
    author: '',
    metric_name: 'topic_rank',
    metric_value: i + 1,
  }));
}

// --- Mastodon: trending posts + trending hashtags ---
function parseMastodonStatuses(arr) {
  return arr.map((s, i) => {
    const media = s.media_attachments || [];
    const v = media.find((m) => m.type === 'video' || m.type === 'gifv');
    const img = media.find((m) => m.type === 'image');
    const text = strip(s.content);
    return row({
      platform: 'mastodon',
      category: (s.tags || [])[0]?.name || hashtag(text) || 'trending_post',
      rank: i + 1,
      title: clip(text || '(media post)', 300),
      url: s.url || s.uri || '',
      video_url: v?.url || v?.remote_url || '',
      has_video: v ? 'yes' : 'no',
      video_thumbnail: v?.preview_url || img?.preview_url || '',
      author: s.account?.acct || '',
      metric_name: 'boosts',
      metric_value: s.reblogs_count ?? null,
      context: `favourites=${s.favourites_count ?? 0}; replies=${s.replies_count ?? 0}`,
      published_at: s.created_at || '',
    });
  });
}

function parseMastodonTags(arr) {
  return arr.map((t, i) => {
    const h = (t.history || [])[0] || {};
    return row({
      platform: 'mastodon',
      category: 'trending_hashtag',
      rank: i + 1,
      title: '#' + (t.name || ''),
      url: t.url || '',
      metric_name: 'uses_24h',
      metric_value: h.uses ? Number(h.uses) : null,
      context: `accounts=${h.accounts ?? 0}`,
    });
  });
}

// --- YouTube: most popular chart (MAIN CHANNEL, needs a free API key) ---
function parseYouTube(data, geo) {
  return (data.items || []).map((v, i) => row({
    platform: 'youtube',
    geo: geo || 'global',
    category: YT_CATS[String(v.snippet?.categoryId)] || 'Unknown',
    rank: i + 1,
    title: v.snippet?.title || '',
    url: 'https://www.youtube.com/watch?v=' + v.id,
    video_url: 'https://www.youtube.com/watch?v=' + v.id,
    has_video: 'yes',
    video_thumbnail: v.snippet?.thumbnails?.high?.url || v.snippet?.thumbnails?.default?.url || '',
    author: v.snippet?.channelTitle || '',
    metric_name: 'views',
    metric_value: v.statistics?.viewCount ? Number(v.statistics.viewCount) : null,
    context: (v.snippet?.tags || []).slice(0, 5).join(', '),
    published_at: v.snippet?.publishedAt || '',
  }));
}


// --- Firecrawl SCRAPE of a subreddit listing page -> markdown ---
function parseFirecrawlReddit(md, source_url) {
  const links = [...String(md).matchAll(/\[([^\]]*)\]\((https?:\/\/[^\s)]+)\)/g)]
    .map((m) => ({ text: dec(m[1]).trim(), url: m[2].trim() }));
  const out = [];
  const seenPost = new Set();
  links.forEach((l, i) => {
    const m = l.url.match(/reddit\.com\/r\/([^/]+)\/comments\/([a-z0-9]+)/i);
    if (!m) return;
    const post_id = m[2];
    if (seenPost.has(post_id)) return;
    seenPost.add(post_id);
    const prev = links[i - 1];
    const titleFromPrev = prev && !/reddit\.com\/r\/[^/]+\/comments\//i.test(prev.url) &&
      prev.text && !/^(comments|permalink|share|save|report)$/i.test(prev.text);
    const title = titleFromPrev ? prev.text : l.text;
    const outbound = titleFromPrev ? prev.url : '';
    if (!title || /^(comments|permalink)$/i.test(title)) return;
    const video = VIDEO_RE.test(outbound) ? outbound : '';
    out.push(row({
      platform: 'reddit',
      category: m[1],
      rank: out.length + 1,
      title,
      url: l.url,
      video_url: video,
      has_video: video ? 'yes' : 'no',
      metric_name: 'top_rank_24h',
      metric_value: out.length + 1,
      context: !video && outbound ? outbound : '',
      published_at: '',
    }));
  });
  return out;
}

// --- Firecrawl SEARCH results (TikTok / Instagram / LinkedIn discovery) ---
function platformFromUrl(u) {
  const s = String(u);
  if (/tiktok\.com/i.test(s)) return 'tiktok';
  if (/instagram\.com/i.test(s)) return 'instagram';
  if (/linkedin\.com/i.test(s)) return 'linkedin';
  if (/youtube\.com|youtu\.be/i.test(s)) return 'youtube';
  return 'web';
}

function parseFirecrawlSearch(d) {
  // the node may hand back {data:{web:[]}}, {web:[]}, a bare array, or one result
  const core = d && d.data && !Array.isArray(d.data) ? d.data : d;
  let results = [];
  if (Array.isArray(core)) results = core;
  else if (core && typeof core === 'object') {
    results = [].concat(core.web || [], core.news || [], core.results || []);
    if (!results.length && core.url) results = [core];
  }
  return results.filter((r) => r && r.url).map((r, i) => {
    const video = VIDEO_RE.test(r.url) ? r.url : '';
    return row({
      platform: platformFromUrl(r.url),
      category: 'discovered_trend',
      rank: i + 1,
      title: clip(dec(r.title || r.metadata?.title || '(untitled)'), 300),
      url: r.url,
      video_url: video,
      has_video: video ? 'yes' : 'no',
      author: (String(r.url).match(/^https?:\/\/([^/]+)/) || [])[1] || '',
      metric_name: 'search_rank',
      metric_value: i + 1,
      context: clip(dec(r.description || r.metadata?.description || ''), 300),
    });
  });
}

function normalizeBody(body, geo) {
  const s = String(body || '').trim();
  if (!s) return [];
  if (s.startsWith('<')) return /reddit\.com/.test(s) && /<entry>/.test(s) ? parseReddit(s) : [];
  if (!s.startsWith('{') && !s.startsWith('[')) {
    // plain markdown from a Firecrawl scrape
    return /reddit\.com\/r\/[^/]+\/comments\//i.test(s) ? parseFirecrawlReddit(s, '') : [];
  }
  let d;
  try { d = JSON.parse(s); } catch (e) { return []; }
  if (Array.isArray(d)) {
    if (!d.length) return [];
    if (d[0].account || d[0].media_attachments) return parseMastodonStatuses(d);
    if (d[0].history && d[0].name) return parseMastodonTags(d);
    if (d[0].url) return parseFirecrawlSearch(d);
    return [];
  }
  if (Array.isArray(d.data) && d.data.length && d.data[0] && d.data[0].url) return parseFirecrawlSearch(d.data);
  if (d.feed) return parseBlueskyFeed(d);
  if (d.topics) return parseBlueskyTopics(d);
  if (d.items || d.kind === 'youtube#videoListResponse') return parseYouTube(d, geo);
  // Firecrawl node output
  const fcCore = d.data && !Array.isArray(d.data) ? d.data : d;
  const fcMd = fcCore.markdown || fcCore.content || '';
  if (fcMd && /reddit\.com\/r\/[^/]+\/comments\//i.test(fcMd)) return parseFirecrawlReddit(fcMd, fcCore.metadata?.sourceURL || '');
  if (fcCore.web || fcCore.news || fcCore.results) return parseFirecrawlSearch(d);
  if (fcCore.url) return parseFirecrawlSearch(fcCore); // one search result per item
  return [];
}

// ---- run over every incoming response (YouTube lane + social lane) ----
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  let body = j.data ?? j.body;
  if (body === undefined || body === null || body === '') {
    // Firecrawl nodes can hand back a flat object instead of {data:...}
    body = (j.markdown || j.web || j.news || j.results || j.url || j.items || j.feed || j.topics) ? j : '';
  }
  let rows = [];
  try {
    rows = normalizeBody(typeof body === 'object' ? JSON.stringify(body) : body, j.geo);
  } catch (e) {
    rows = [];
  }
  for (const t of rows) {
    const trend_key = `${t.platform}|${t.geo}|${t.url || t.title}`.toLowerCase();
    if (seen.has(trend_key)) continue;
    seen.add(trend_key);
    out.push({ json: { ...t, trend_key, scraped_at } });
  }
}

if (out.length === 0) {
  throw new Error('No social trends parsed - check the responses in the two Fetch nodes.');
}

// ---- YouTube: merge the per-region charts into ONE worldwide ranking ----
const ytMap = new Map();
const rest = [];
for (const item of out) {
  const t = item.json;
  if (t.platform !== 'youtube') { rest.push(item); continue; }
  const key = t.url;
  const cur = ytMap.get(key);
  if (!cur) {
    ytMap.set(key, { row: { ...t, geo: 'worldwide' }, regions: [t.geo] });
  } else {
    cur.regions.push(t.geo);
    cur.row.metric_value = Math.max(cur.row.metric_value || 0, t.metric_value || 0);
  }
}
const ytRows = [...ytMap.values()].map(({ row, regions }) => {
  const uniq = [...new Set(regions)].filter(r => r && r !== 'global');
  return {
    n: uniq.length,
    json: {
      ...row,
      context: `trending in ${uniq.length} region(s): ${uniq.join(', ')}`,
      trend_key: `youtube|worldwide|${row.url}`.toLowerCase(),
    },
  };
});
// biggest worldwide spread first, then raw view count
ytRows.sort((a, b) => b.n - a.n || (b.json.metric_value || 0) - (a.json.metric_value || 0));
ytRows.forEach((r, i) => { r.json.rank = i + 1; });

out.length = 0;
out.push(...ytRows.map(r => ({ json: r.json })), ...rest);

// YouTube (main channel) first, then anything else carrying a video link.
const prio = (p) => (p === 'youtube' ? 0 : 1);
out.sort((a, b) =>
  prio(a.json.platform) - prio(b.json.platform) ||
  (b.json.has_video === 'yes') - (a.json.has_video === 'yes') ||
  a.json.platform.localeCompare(b.json.platform) ||
  a.json.rank - b.json.rank);

return out;

// Firecrawl SEARCH covers the platforms with no open API (TikTok, Instagram,
// LinkedIn). Search takes a natural-language query, not a URL - it finds and
// scrapes matching pages, so results are discovery-grade, not official metrics.
const queries = [
  'trending TikTok videos this week',
  'viral Instagram reels trending this week',
  'most engaged LinkedIn posts this week',
];

return queries.map(query => ({ json: { query } }));

// Hashtag seeds for the TikTok Actor. Kept separate from the Instagram seed so
// each Actor run stays independently tunable.
return [{ json: { tags: ['fyp', 'trending', 'viral'] } }];

// Normalize TikTok + Instagram Actor output into the same 16-column shape that
// "Normalize trends" emits, so both streams can share the Sheets append.
const scraped_at = new Date().toISOString();
const out = [];

const clean = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

for (const item of $input.all()) {
  const it = item.json || {};
  if (it.error) continue;

  // TikTok items carry webVideoUrl / diggCount; Instagram carry shortCode / likesCount.
  const isTikTok = Boolean(it.webVideoUrl || it.diggCount != null || it.playCount != null);
  const platform = isTikTok ? 'tiktok' : 'instagram';

  const url = isTikTok
    ? (it.webVideoUrl || '')
    : (it.url || (it.shortCode ? `https://www.instagram.com/p/${it.shortCode}/` : ''));
  if (!url) continue;

  const title = clean(isTikTok ? it.text : (it.caption ?? it.text)).slice(0, 300);
  const author = isTikTok
    ? clean(it.authorMeta?.name || it.authorMeta?.nickName)
    : clean(it.ownerUsername || it.ownerFullName);

  const is_video = isTikTok || it.type === 'Video' || Boolean(it.videoUrl);
  const metric_value = isTikTok ? num(it.playCount || it.diggCount) : num(it.likesCount);

  out.push({ json: {
    platform,
    geo: 'worldwide',
    category: isTikTok
      ? clean((it.hashtags || []).map(h => h.name || h).slice(0, 3).join(', '))
      : clean((it.hashtags || []).slice(0, 3).join(', ')),
    rank: 0,
    title: title || '(no caption)',
    url,
    video_url: is_video ? (it.videoUrl || it.videoUrlNoWaterMark || url) : '',
    has_video: is_video ? 'yes' : 'no',
    video_thumbnail: it.covers?.default || it.videoMeta?.coverUrl || it.displayUrl || '',
    author,
    metric_name: isTikTok ? 'plays' : 'likes',
    metric_value,
    context: isTikTok
      ? `${num(it.diggCount)} likes, ${num(it.commentCount)} comments`
      : `${num(it.commentsCount)} comments`,
    published_at: it.createTimeISO || it.timestamp || '',
    scraped_at,
    trend_key: `${platform}|worldwide|${url}`.toLowerCase(),
  }});
}

// Rank within each platform by its own metric.
const byPlatform = {};
out.sort((a, b) => b.json.metric_value - a.json.metric_value);
for (const o of out) {
  byPlatform[o.json.platform] = (byPlatform[o.json.platform] || 0) + 1;
  o.json.rank = byPlatform[o.json.platform];
}

return out;
